mapper.select:
SELECT LOG_ID AS logId,
	   ACTION AS action,
	   CREATED_AT AS createdAt ,
	   DEL_YN AS delYN
FROM  KIOSK_LOG

	DEL_YN = 'N'

		AND LOG_ID = #{logId}


		AND ACTION = #{action}


		AND DATE(CREATED_AT) = #{createdAt}

